<template><el-card header="批量命令执行"><el-select v-model="assetIds" multiple style="width:100%"><el-option v-for="a in assets" :key="a.id" :label="a.ip_address" :value="a.id"/></el-select><el-input v-model="command" type="textarea" style="margin-top:12px"/><el-button type="primary" @click="run" style="margin-top:12px">执行</el-button><pre>{{result}}</pre></el-card></template><script setup>import{ref,onMounted}from"vue";import{getAssetList,batchExecApi}from"../../api/exec";const assets=ref([]),assetIds=ref([]),command=ref("uptime"),result=ref("");onMounted(async()=>assets.value=(await getAssetList()).data);const run=async()=>result.value=JSON.stringify((await batchExecApi({asset_ids:assetIds.value,command:command.value})).data,null,2)</script>
